	@Test
	public void nullableIriLookupRemainsSourceCompatible() throws Exception {
		JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
		assertNotNull(compiler, "the test runtime must provide the Java compiler");
		Path sourceFile = temporaryDirectory.resolve("NullableLookupCompatibility.java");
		Path outputDirectory = temporaryDirectory.resolve("compiled");
		Files.createDirectories(outputDirectory);
		Files.writeString(sourceFile, """
				import org.eclipse.rdf4j.model.base.CoreDatatype;
				public final class NullableLookupCompatibility {
					public static CoreDatatype lookup() {
						return CoreDatatype.from(null);
					}
				}
				""");

		String classPath = String.join(File.pathSeparator,
				Path.of(CoreDatatype.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toString(),
				Path.of(Experimental.class.getProtectionDomain().getCodeSource().getLocation().toURI()).toString());
		ByteArrayOutputStream compilerErrors = new ByteArrayOutputStream();
		int result = compiler.run(null, null, compilerErrors,
				"-proc:none", "-classpath", classPath,
				"-d", outputDirectory.toString(), sourceFile.toString());

		assertEquals(0, result, compilerErrors.toString());
		assertSame(CoreDatatype.NONE, CoreDatatype.from((IRI) null));

		sourceFile = temporaryDirectory.resolve("StringLookupCompatibility.java");
		Files.writeString(sourceFile, """
				import org.eclipse.rdf4j.model.base.CoreDatatype;
				public final class StringLookupCompatibility {
					public static void main(String[] args) {
						if (CoreDatatype.fromString(null) != CoreDatatype.NONE
								|| CoreDatatype.fromString("http://www.w3.org/2001/XMLSchema#string")
										!= CoreDatatype.XSD.STRING
								|| CoreDatatype.fromString("urn:unknown") != CoreDatatype.NONE) {
							throw new AssertionError("string datatype lookup changed its results");
						}
					}
				}
				""");
		ByteArrayOutputStream stringCompilerErrors = new ByteArrayOutputStream();
		int stringResult = compiler.run(null, null, stringCompilerErrors,
				"-proc:none", "-classpath", classPath,
				"-d", outputDirectory.toString(), sourceFile.toString());
		assertEquals(0, stringResult, stringCompilerErrors.toString());

		String javaExecutable = System.getProperty("os.name").toLowerCase(Locale.ROOT).contains("win")
				? "java.exe"
				: "java";
		Process process = new ProcessBuilder(
				Path.of(System.getProperty("java.home"), "bin", javaExecutable).toString(),
				"-classpath", classPath + File.pathSeparator + outputDirectory,
				"StringLookupCompatibility")
						.redirectErrorStream(true)
						.start();
		String processOutput = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
		assertEquals(0, process.waitFor(), processOutput);
	}

